     1	import 'dart:async';
     2	
     3	import 'package:flutter_bloc/flutter_bloc.dart';
     4	import 'package:fpdart/fpdart.dart';
     5	
     6	import '../../../../core/failure/failure.dart';
     7	import '../../domain/entities/chat_message.dart';
     8	import '../../domain/entities/chat_session.dart';
     9	import '../../domain/entities/chat_stream_event.dart';
    10	import '../../domain/repositories/chat_repository.dart';
    11	import 'chat_state.dart';
    12	
    13	/// Drives `ChatScreen` — a DI `lazySingleton` (Code Map, mirroring
    14	/// `MeusRegistrosCubit`): long-lived, so returning to Home/Chat within the
    15	/// same app session never re-bootstraps the session/history it already
    16	/// loaded (`init()`'s own no-op guard below).
    17	class ChatCubit extends Cubit<ChatState> {
    18	  ChatCubit(this._repository) : super(const ChatBootstrapLoading());
    19	
    20	  final ChatRepository _repository;
    21	
    22	  StreamSubscription<Either<Failure, ChatStreamEvent>>? _sendSubscription;
    23	
    24	  /// The in-flight [sendMessage]'s own completer, if any — [close] must
    25	  /// complete it itself, since cancelling [_sendSubscription] never fires
    26	  /// `onDone`/`onError` (review fix: `cancel()` alone left `sendMessage()`'s
    27	  /// returned `Future` permanently unresolved when the cubit closed mid-send).
    28	  Completer<void>? _sendCompleter;
    29	
    30	  /// Monotonic counter behind every locally generated [ChatUiMessage.id]
    31	  /// (Code Map) — never the server's own message id (see `ChatStreamEvent`'s
    32	  /// own doc on why `message_created`'s id goes unused here).
    33	  int _localIdCounter = 0;
    34	
    35	  /// Whether a send is actively in flight right now — tracked locally
    36	  /// rather than by scanning [ChatState.messages] for a persisted
    37	  /// `streaming` status, since a message loaded from history/cache can
    38	  /// legitimately carry that same status (e.g. one left over from an
    39	  /// earlier dropped response, the I/O matrix's own scenario) without a
    40	  /// send actually being in progress; scanning for it would permanently
    41	  /// disable the composer in that case.
    42	  bool _isSending = false;
    43	
    44	  /// An in-flight bootstrap, if any — reused by a concurrent `init()` call
    45	  /// instead of starting a second bootstrap, so two near-simultaneous
    46	  /// callers (e.g. two mounts before the first resolves) never both
    47	  /// observe "no sessions" and both call `createSession()` (Boundaries:
    48	  /// "silently ensure *one* Chat Session exists").
    49	  Future<void>? _initFuture;
    50	
    51	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
    52	  /// `sessionId`, on `ChatCubit` (never Hive) — survives session switches
    53	  /// within one app run, resets on restart." Lives on this long-lived
    54	  /// `lazySingleton` cubit itself (Design Notes), never on [ChatReady] —
    55	  /// a state value would otherwise have to be threaded through every
    56	  /// unrelated `copyWith` call just to avoid losing it.
    57	  final Map<String, double> _scrollOffsets = {};
    58	
    59	  /// Boundaries: "On opening Home/Chat, silently ensure one Chat Session
    60	  /// exists (reuse the most recent from `chat-sessions-list`, else
    61	  /// `chat-sessions-create` with no title)". A no-op once already
    62	  /// [ChatReady] — `ChatScreen.initState()` calls this unconditionally on
    63	  /// every mount, but a `lazySingleton` cubit may already be bootstrapped
    64	  /// from an earlier visit.
    65	  Future<void> init() {
    66	    if (state is ChatReady || isClosed) {
    67	      return Future.value();
    68	    }
    69	    return _initFuture ??= _bootstrap().whenComplete(() => _initFuture = null);
    70	  }
    71	
    72	  Future<void> _bootstrap() async {
    73	    emit(const ChatBootstrapLoading());
    74	
    75	    final sessionsResult = await _repository.listSessions();
    76	    if (isClosed) {
    77	      return;
    78	    }
    79	    // Captured by the closures below so the resulting [ChatReady] can
    80	    // carry every known session (Code Map: "capture resolved sessions
    81	    // into the emitted ChatReady"), not just the one picked to reuse.
    82	    List<ChatSession> sessions = const [];
    83	    final Either<Failure, ChatSession> sessionResult = await sessionsResult
    84	        .match((failure) async => left(failure), (fetchedSessions) async {
    85	          if (fetchedSessions.isEmpty) {
    86	            final createResult = await _repository.createSession();
    87	            return createResult.match((failure) => left(failure), (session) {
    88	              sessions = [session];
    89	              return right(session);
    90	            });
    91	          }
    92	          sessions = fetchedSessions;
    93	          // "reuse the most recent" — defensively re-sorts rather than
    94	          // trusting `listSessions()`'s own ordering (its offline-cache
    95	          // fallback already sorts `updatedAt` desc, but the live
    96	          // server response's own ordering isn't documented either
    97	          // way). `tryParse` (never `parse`) — same crash-safe pattern as
    98	          // `AppDrawer`'s own session sort (review finding "Crash risk in
    99	          // the new `_ConversasSection` sort"): a malformed `updatedAt`
   100	          // must never crash bootstrap itself, so it falls back to the
   101	          // epoch and simply sorts last instead of throwing.
   102	          final mostRecent = [...fetchedSessions]..sort(
   103	            (a, b) => (DateTime.tryParse(b.updatedAt) ?? DateTime(0))
   104	                .compareTo(DateTime.tryParse(a.updatedAt) ?? DateTime(0)),
   105	          );
   106	          return right(mostRecent.first);
   107	        });
   108	    if (isClosed) {
   109	      return;
   110	    }
   111	
   112	    await sessionResult.match(
   113	      (failure) async {
   114	        if (!isClosed) {
   115	          emit(ChatBootstrapError(failure));
   116	        }
   117	      },
   118	      (session) async {
   119	        final messagesResult = await _repository.listMessages(session.id);
   120	        if (isClosed) {
   121	          return;
   122	        }
   123	        messagesResult.match(
   124	          (failure) => emit(ChatBootstrapError(failure)),
   125	          (messages) => emit(
   126	            ChatReady(
   127	              sessionId: session.id,
   128	              messages: messages.map(_fromDomain).toList(),
   129	              sessions: sessions,
   130	            ),
   131	          ),
   132	        );
   133	      },
   134	    );
   135	  }
   136	
   137	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
   138	  /// `sessionId`" — `ChatScreen`'s own `ScrollController` listener calls
   139	  /// this on every scroll update, so whichever offset a session was last
   140	  /// left at is always the one [switchSession] hands back when that
   141	  /// session becomes active again.
   142	  void recordScrollOffset(String sessionId, double offset) {
   143	    _scrollOffsets[sessionId] = offset;
   144	  }
   145	
   146	  /// I/O matrix: "Switch session"/"Switch to already-active session" —
   147	  /// a no-op [Right] when [sessionId] is already [ChatReady.sessionId]
   148	  /// (the drawer still closes, nothing reloads/re-fetches); otherwise
   149	  /// fetches that session's own history via `listMessages` (reused as-is,
   150	  /// Code Map) and makes it active, handing [ChatReady.restoreScrollOffset]
   151	  /// whatever [recordScrollOffset] last captured for it (`null` if this
   152	  /// session was never scrolled in this app run — `ChatScreen`'s own cue
   153	  /// to jump to the bottom instead). A no-op while bootstrap hasn't
   154	  /// resolved yet, same guard shape as [sendMessage].
   155	  Future<Either<Failure, Unit>> switchSession(String sessionId) async {
   156	    final current = state;
   157	    if (current is! ChatReady) {
   158	      return right(unit);
   159	    }
   160	    if (sessionId == current.sessionId) {
   161	      return right(unit);
   162	    }
   163	    // Review finding: "Cross-session stream leakage" — an AI response
   164	    // still streaming into the *old* session must never be left running
   165	    // once we switch away from it; its orphaned subscription's
   166	    // `onData`/`onDone` would otherwise go on to mutate whichever session
   167	    // becomes active next.
   168	    await _cancelInFlightSend();
   169	    final messagesResult = await _repository.listMessages(sessionId);
   170	    if (isClosed) {
   171	      return right(unit);
   172	    }
   173	    return messagesResult.match(
   174	      (failure) {
   175	        // Review fix: `_cancelInFlightSend()` above only resets the
   176	        // internal `_isSending` guard, not the `ChatReady.isSending` the
   177	        // composer gates on (`canSend = ... && !state.isSending`) — on a
   178	        // failed switch we're staying on `current`, so its stale
   179	        // `isSending: true` must be flipped back here or the composer
   180	        // would stay disabled for the rest of the app run.
   181	        if (!isClosed && current.isSending) {
   182	          emit(current.copyWith(isSending: false));
   183	        }
   184	        return left(failure);
   185	      },
   186	      (messages) {
   187	        if (!isClosed) {
   188	          emit(
   189	            ChatReady(
   190	              sessionId: sessionId,
   191	              messages: messages.map(_fromDomain).toList(),
   192	              sessions: current.sessions,
   193	              restoreScrollOffset: _scrollOffsets[sessionId],
   194	            ),
   195	          );
   196	        }
   197	        return right(unit);
   198	      },
   199	    );
   200	  }
   201	
   202	  /// I/O matrix: "New session online"/"New session offline" — calls
   203	  /// `createSession()` (reused as-is, Code Map; already blocked offline
   204	  /// at the repository level, Boundaries). On any [Left] (including
   205	  /// [Failure.networkOffline]), the current session is left completely
   206	  /// untouched — no state is emitted at all, only the [Failure] is handed
   207	  /// back for `AppDrawer` to surface as a transient `SnackBar`
   208	  /// (Boundaries). On success, the new session opens empty and becomes
   209	  /// active, prepended to [ChatReady.sessions].
   210	  Future<Either<Failure, Unit>> startNewSession() async {
   211	    final current = state;
   212	    if (current is! ChatReady) {
   213	      return right(unit);
   214	    }
   215	    // Review finding: "Cross-session stream leakage" — same rationale as
   216	    // [switchSession]'s own cancellation above; a brand new session is
   217	    // never the same session as [current], so this always needs to run
   218	    // (unlike [switchSession], there's no same-session no-op branch to
   219	    // skip it for).
   220	    await _cancelInFlightSend();
   221	    final result = await _repository.createSession();
   222	    if (isClosed) {
   223	      return right(unit);
   224	    }
   225	    return result.match(
   226	      (failure) {
   227	        // Review fix: same stuck-`isSending` risk as [switchSession] — a
   228	        // failed `createSession()` leaves `current` active, so its stale
   229	        // `isSending: true` (left behind by `_cancelInFlightSend()`
   230	        // above, which never emits) must be flipped back here.
   231	        if (!isClosed && current.isSending) {
   232	          emit(current.copyWith(isSending: false));
   233	        }
   234	        return left(failure);
   235	      },
   236	      (session) {
   237	        if (!isClosed) {
   238	          emit(
   239	            ChatReady(
   240	              sessionId: session.id,
   241	              messages: const [],
   242	              sessions: [session, ...current.sessions],
   243	            ),
   244	          );
   245	        }
   246	        return right(unit);
   247	      },
   248	    );
   249	  }
   250	
   251	  ChatUiMessage _fromDomain(ChatMessage message) => ChatUiMessage(
   252	    id: message.id,
   253	    role: message.role,
   254	    content: message.content,
   255	    status: message.status,
   256	  );
   257	
   258	  /// Boundaries: optimistic user bubble, then subscribes to
   259	  /// `ChatRepository.sendMessage`'s own stream, appending tokens as they
   260	  /// arrive and finalizing/failing the AI bubble on `done`/any `Left` —
   261	  /// the bubble's own [ChatUiMessage.content] is never cleared on failure
   262	  /// (I/O matrix), only its [ChatUiMessage.status] changes.
   263	  ///
   264	  /// A no-op while [state] isn't [ChatReady] (bootstrap still in flight
   265	  /// or failed — the composer is disabled in that case anyway), while
   266	  /// [content] is blank once trimmed, or while [_isSending] is already
   267	  /// true — this story never races two concurrent sends against the one
   268	  /// in-memory session (Boundaries: no offline lock/composer-disable UI
   269	  /// of its own exists yet, Story 6.3's job, so this guard is the one
   270	  /// thing standing in for it here). Deliberately not keyed off any
   271	  /// loaded message's persisted `streaming` status — a message restored
   272	  /// from history/cache can legitimately carry that status without a
   273	  /// send actually being in flight (I/O matrix: mid-stream drop).
   274	  Future<void> sendMessage(String content) async {
   275	    final trimmed = content.trim();
   276	    if (trimmed.isEmpty) {
   277	      return;
   278	    }
   279	    final current = state;
   280	    if (current is! ChatReady) {
   281	      return;
   282	    }
   283	    if (_isSending) {
   284	      return;
   285	    }
   286	    _isSending = true;
   287	
   288	    final userMessage = ChatUiMessage(
   289	      id: _nextLocalId(),
   290	      role: ChatMessageRole.user,
   291	      content: trimmed,
   292	      status: ChatMessageStatus.complete,
   293	    );
   294	    final aiMessage = ChatUiMessage(
   295	      id: _nextLocalId(),
   296	      role: ChatMessageRole.assistant,
   297	      content: '',
   298	      status: ChatMessageStatus.streaming,
   299	    );
   300	    emit(
   301	      current.copyWith(
   302	        messages: [...current.messages, userMessage, aiMessage],
   303	        isSending: true,
   304	      ),
   305	    );
   306	
   307	    await _sendSubscription?.cancel();
   308	    final completer = Completer<void>();
   309	    _sendCompleter = completer;
   310	    _sendSubscription = _repository
   311	        .sendMessage(current.sessionId, trimmed)
   312	        .listen(
   313	          (event) {
   314	            event.match(
   315	              (failure) => _markFailed(aiMessage.id),
   316	              (streamEvent) => _applyStreamEvent(aiMessage.id, streamEvent),
   317	            );
   318	          },
   319	          onError: (Object _, StackTrace _) {
   320	            // RNF09: no exception escapes the cubit — a stream-level
   321	            // error (shouldn't happen, `ChatRemoteDataSource.sendMessage`
   322	            // never lets one through unmapped) still only fails the
   323	            // bubble, never crashes.
   324	            _markFailed(aiMessage.id);
   325	            _finishSending();
   326	            if (!completer.isCompleted) {
   327	              completer.complete();
   328	            }
   329	            _sendCompleter = null;
   330	          },
   331	          onDone: () {
   332	            _finishSending();
   333	            if (!completer.isCompleted) {
   334	              completer.complete();
   335	            }
   336	            _sendCompleter = null;
   337	          },
   338	          cancelOnError: false,
   339	        );
   340	    await completer.future;
   341	  }
   342	
   343	  /// Clears both the internal re-entrancy guard and the UI-facing
   344	  /// [ChatReady.isSending] signal once a send's stream has ended (`done`,
   345	  /// an in-band error, or a stream-level error) — the single place both
   346	  /// flip back together.
   347	  void _finishSending() {
   348	    _isSending = false;
   349	    if (isClosed) {
   350	      return;
   351	    }
   352	    final current = state;
   353	    if (current is ChatReady) {
   354	      emit(current.copyWith(isSending: false));
   355	    }
   356	  }
   357	
   358	  void _applyStreamEvent(String aiMessageId, ChatStreamEvent event) {
   359	    if (isClosed) {
   360	      return;
   361	    }
   362	    final current = state;
   363	    if (current is! ChatReady) {
   364	      return;
   365	    }
   366	    switch (event) {
   367	      case ChatMessageCreatedEvent():
   368	        // Design Notes: the persisted *user*-message id — no UI-facing
   369	        // use yet in this story (Story 6.3's retry call is the first
   370	        // consumer).
   371	        break;
   372	      case ChatTokenEvent(delta: final delta):
   373	        emit(
   374	          current.copyWith(
   375	            messages: [
   376	              for (final message in current.messages)
   377	                if (message.id == aiMessageId)
   378	                  message.copyWith(content: message.content + delta)
   379	                else
   380	                  message,
   381	            ],
   382	          ),
   383	        );
   384	      case ChatDoneEvent():
   385	        emit(
   386	          current.copyWith(
   387	            messages: [
   388	              for (final message in current.messages)
   389	                if (message.id == aiMessageId)
   390	                  message.copyWith(status: ChatMessageStatus.complete)
   391	                else
   392	                  message,
   393	            ],
   394	          ),
   395	        );
   396	    }
   397	  }
   398	
   399	  /// I/O matrix: "Mid-stream drop"/"In-band `error` event" — marks the one
   400	  /// bubble `failed`, by id, leaving its already-streamed-in text exactly
   401	  /// as-is (never cleared, Boundaries).
   402	  void _markFailed(String aiMessageId) {
   403	    if (isClosed) {
   404	      return;
   405	    }
   406	    final current = state;
   407	    if (current is! ChatReady) {
   408	      return;
   409	    }
   410	    emit(
   411	      current.copyWith(
   412	        messages: [
   413	          for (final message in current.messages)
   414	            if (message.id == aiMessageId)
   415	              message.copyWith(status: ChatMessageStatus.failed)
   416	            else
   417	              message,
   418	        ],
   419	      ),
   420	    );
   421	  }
   422	
   423	  String _nextLocalId() => 'local-${_localIdCounter++}';
   424	
   425	  /// Review finding: "Cross-session stream leakage" — [switchSession]/
   426	  /// [startNewSession] call this before touching anything else whenever
   427	  /// they're about to make a *different* session active, so a response
   428	  /// still streaming into the session being left behind can never go on
   429	  /// to mutate the one that replaces it. Exactly [close]'s own cleanup
   430	  /// below (cancel the subscription, resolve the stranded [sendMessage]
   431	  /// caller, clear the re-entrancy guard), just without closing the cubit
   432	  /// itself — a no-op when nothing is actually in flight.
   433	  Future<void> _cancelInFlightSend() async {
   434	    if (!_isSending) {
   435	      return;
   436	    }
   437	    await _sendSubscription?.cancel();
   438	    _sendSubscription = null;
   439	    final completer = _sendCompleter;
   440	    if (completer != null && !completer.isCompleted) {
   441	      completer.complete();
   442	    }
   443	    _sendCompleter = null;
   444	    _isSending = false;
   445	  }
   446	
   447	  @override
   448	  Future<void> close() {
   449	    _sendSubscription?.cancel();
   450	    final completer = _sendCompleter;
   451	    if (completer != null && !completer.isCompleted) {
   452	      completer.complete();
   453	    }
   454	    _sendCompleter = null;
   455	    return super.close();
   456	  }
   457	}

---chat_repository_impl---
     1	// The constructor keeps public named params distinct from the private
     2	// fields they initialize, same convention `entries_repository_impl.dart`
     3	// already documents.
     4	// ignore_for_file: prefer_initializing_formals
     5	import 'package:fpdart/fpdart.dart';
     6	import 'package:hive_ce/hive_ce.dart';
     7	
     8	import '../../../../core/failure/failure.dart';
     9	import '../../domain/entities/chat_message.dart';
    10	import '../../domain/entities/chat_session.dart';
    11	import '../../domain/entities/chat_stream_event.dart';
    12	import '../../domain/repositories/chat_repository.dart';
    13	import '../datasources/chat_remote_data_source.dart';
    14	import '../models/chat_message_dto.dart';
    15	import '../models/chat_session_dto.dart';
    16	
    17	/// On success, [listSessions]/[createSession]/[listMessages] each write
    18	/// through to their own Hive box *before* returning `right(...)`, same
    19	/// "persist then return" ordering `EntriesRepositoryImpl` already uses.
    20	class ChatRepositoryImpl implements ChatRepository {
    21	  ChatRepositoryImpl({
    22	    required ChatRemoteDataSource remoteDataSource,
    23	    required Box<Map> sessionsBox,
    24	    required Box<Map> messagesBox,
    25	  }) : _remoteDataSource = remoteDataSource,
    26	       _sessionsBox = sessionsBox,
    27	       _messagesBox = messagesBox;
    28	
    29	  final ChatRemoteDataSource _remoteDataSource;
    30	  final Box<Map> _sessionsBox;
    31	  final Box<Map> _messagesBox;
    32	
    33	  @override
    34	  Future<Either<Failure, List<ChatSession>>> listSessions() async {
    35	    final result = await _remoteDataSource.listSessions();
    36	    return result.match(
    37	      (failure) async {
    38	        // `requirements.md`: "`GET /chat/sessions` — works offline
    39	        // (cache)" — same cursor-null-page cache-fallback convention
    40	        // `EntriesRepositoryImpl.list()` already uses; every other
    41	        // `Failure` (e.g. `authExpired`) propagates as `Left`, unmapped.
    42	        if (failure is NetworkOffline || failure is NetworkTimeout) {
    43	          return _cachedSessions();
    44	        }
    45	        return left(failure);
    46	      },
    47	      (dtos) async {
    48	        try {
    49	          await _sessionsBox.putAll({
    50	            for (final dto in dtos) dto.id: dto.toJson(),
    51	          });
    52	        } catch (error) {
    53	          // A thrown Hive/disk exception must never escape unmapped
    54	          // (RNF09) — same fallback `EntriesRepositoryImpl`'s own writes
    55	          // already use.
    56	          return left(Failure.malformedResponse(message: error.toString()));
    57	        }
    58	        return right(dtos.map((dto) => dto.toEntity()).toList());
    59	      },
    60	    );
    61	  }
    62	
    63	  @override
    64	  Future<Either<Failure, ChatSession>> createSession() async {
    65	    final result = await _remoteDataSource.createSession();
    66	    return result.match(
    67	      // Blocked offline (`requirements.md`) — no cache fallback, unlike
    68	      // [listSessions]/[listMessages]: every `Failure` propagates as
    69	      // `Left`, unmapped.
    70	      (failure) async => left(failure),
    71	      (dto) async {
    72	        // A local cache-write failure must never mask an already-
    73	        // succeeded remote create: the session exists server-side
    74	        // regardless, so surfacing `left(...)` here would show the user
    75	        // a bootstrap error for an operation that actually succeeded
    76	        // (it would simply be re-fetched via `listSessions()` next
    77	        // time). Best-effort only.
    78	        try {
    79	          await _sessionsBox.put(dto.id, dto.toJson());
    80	        } catch (_) {
    81	          // Intentionally ignored — see above.
    82	        }
    83	        return right(dto.toEntity());
    84	      },
    85	    );
    86	  }
    87	
    88	  @override
    89	  Future<Either<Failure, List<ChatMessage>>> listMessages(
    90	    String sessionId,
    91	  ) async {
    92	    final result = await _remoteDataSource.listMessages(sessionId);
    93	    return result.match(
    94	      (failure) async {
    95	        // `requirements.md`: "`GET /chat/sessions/:id/messages` — works
    96	        // offline (cache)" — same convention [listSessions] above uses.
    97	        if (failure is NetworkOffline || failure is NetworkTimeout) {
    98	          return _cachedMessages(sessionId);
    99	        }
   100	        return left(failure);
   101	      },
   102	      (dtos) async {
   103	        try {
   104	          await _messagesBox.putAll({
   105	            for (final dto in dtos) dto.id: dto.toJson(),
   106	          });
   107	        } catch (error) {
