   159	  /// uses. Each entry is decoded independently, same corrupt-entry
   160	  /// isolation as [_cachedSessions].
   161	  Either<Failure, List<ChatMessage>> _cachedMessages(String sessionId) {
   162	    final messages = <ChatMessage>[];
   163	    for (final json in _messagesBox.values) {
   164	      try {
   165	        final message = ChatMessageDto.fromJson(
   166	          Map<String, dynamic>.from(json),
   167	        ).toEntity();
   168	        if (message.sessionId == sessionId) {
   169	          messages.add(message);
   170	        }
